import { useEffect, useRef } from "react";
import { AccessibilityInfo, Platform } from "react-native";

/**
 * Speak `text` at low priority after current speech. react-native-web has no
 * `announceForAccessibilityWithOptions`; calling it there threw inside an
 * effect and unmounted the whole screen, so fall back to the plain call.
 * Qt supports priority but no native announcement queue; request low priority
 * there without claiming that speech is queued behind another announcement.
 */
export function announce(text: string): void {
  const info: Partial<typeof AccessibilityInfo> = AccessibilityInfo;
  if (typeof info.announceForAccessibilityWithOptions === "function") {
    const qt=String(Platform.OS)==="qnx"||String(Platform.OS)==="marathon";
    info.announceForAccessibilityWithOptions(text, qt?{priority:"low"}:{queue:true,priority:"low"});
  } else {
    info.announceForAccessibility?.(text);
  }
}

/**
 * Announce `status` on iOS each time it changes after mount. Android and web
 * already speak it through the `accessibilityLiveRegion` on the status text;
 * VoiceOver ignores live regions, so without this it heard no phase change.
 */
export function useStatusAnnouncement(status: string): void {
  const previous = useRef(status);
  useEffect(() => {
    if (previous.current === status) return;
    previous.current = status;
    if (Platform.OS === "ios") announce(status);
  }, [status]);
}

import {Button} from '@/components/nyc-tron/ui/components/Button';
import {controlIdentity,useScopedControl,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {assertWaveformRange,type WaveformRange} from '@/components/nyc-tron/ui/components/forge/waveform';
import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
/*
 * Structural references (Mobbin, iOS, structure only):
 * - TIDE, Ambient Noise: time-banded history with a step legend under it.
 * - Suno, Extend: audio card with time readouts along the bottom edge.
 * - How We Feel, voice entry: a dense column strip of audio energy.
 * - Facebook, music clip picker: waveform strip with a time window over it.
 */
import { useRef } from "react";
import { Text, View, type ViewProps } from "react-native";
import { useStore } from "zustand";
import { createStore, type StoreApi } from "zustand/vanilla";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { useStatusAnnouncement } from "@/components/nyc-tron/ui/components/forge/announce";
import {
  SPECTROGRAM_THRESHOLDS_DB, columnsForWidth, describeSpectrogram, frequencyTicks, poolSpectrogram,
  spectrogramRuns, timeTicks, type IntensityStep,
} from "@/components/nyc-tron/ui/components/forge/audio/spectrogram";
import { space, font } from '@/components/nyc-tron/ui/tokens';

/** Load state of a {@linkcode SpectrogramView}. */
export type SpectrogramStatus = "measuring" | "ready" | "error" | "empty";

/** Props for {@linkcode SpectrogramView}. Data comes from the engine's `spectrogram` op. */
export interface SpectrogramViewProps extends Omit<ViewProps, "children">,ScopedControlProps {
  /** Name of the analysed range, used as the group label. */
  readonly label: string;
  /** What to draw: a placeholder, the grid, an error or the empty message. */
  readonly status: SpectrogramStatus;
  /** One row per hop, one dB value per band (floored at -120, full-scale sine about 0). */
  readonly frames: readonly (readonly number[])[];
  /** Band centres in Hz, low to high, log-spaced. */
  readonly bandsHz: readonly number[];
  /** Seconds between frames. */
  readonly hopSeconds: number;
  /** Plot height in pt. @default 160 */
  readonly height?: number;
  readonly visibleRange?:WaveformRange;
  readonly onVisibleRangeCommit?:(range:WaveformRange)=>void|Promise<unknown>;
  /** Shown when `status` is `"error"`. */
  readonly error?: string;
  className?: string;
  unstyled?: boolean;
}

const AXIS = 52;
/** Sequential single-hue steps, light to dark; tokens only. */
const STEP_CLASS: Record<Exclude<IntensityStep, 0>, string> = {
  1: "bg-primary/15", 2: "bg-primary/30", 3: "bg-primary/50", 4: "bg-primary/75", 5: "bg-primary",
};

/**
 * Spectrogram drawn with plain Views: time runs left to right (also in RTL),
 * low frequencies at the bottom. The engine matrix is max-pooled to at most
 * 96 columns by measured width and 32 rows, then mapped to five intensity
 * steps; equal adjacent cells merge into one View, so the drawn count stays
 * at or under 96 x 32.
 */
export function SpectrogramView({scope='spectrogram',revision=0,...props}:SpectrogramViewProps){
 const range=props.visibleRange??{start:0,end:1};assertWaveformRange(range);
 if(props.frames.length>32768||props.bandsHz.length>512||props.frames.length*props.bandsHz.length>2097152||props.frames.some(f=>f.length!==props.bandsHz.length||f.some(n=>!Number.isFinite(n)))||props.bandsHz.some((n,i)=>!Number.isFinite(n)||n<=0||i>0&&n<=props.bandsHz[i-1]!)||!Number.isFinite(props.hopSeconds)||props.hopSeconds<=0||!Number.isFinite(props.frames.length*props.hopSeconds)||!Number.isFinite(props.height??160)||(props.height??160)<44||(props.height??160)>4096)throw new RangeError('Invalid spectrogram data');
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.disabledReason]),guard=useScopedControl(owner,props,props.disabledReason!==undefined);
 return <SpectrogramViewBody {...props} actionError={guard.error} onVisibleRangeCommit={props.onVisibleRangeCommit?range=>guard.run('range',h=>h.onVisibleRangeCommit?.(range)):undefined}/>;
}
function SpectrogramViewBody({actionError,disabledReason,visibleRange={start:0,end:1},onVisibleRangeCommit,

  label, status, frames:sourceFrames, bandsHz, hopSeconds, height = 160, error, className, unstyled = false, style, ...props
}: SpectrogramViewProps&{actionError?:string|null}) {
  const start=Math.floor(visibleRange.start*sourceFrames.length),end=Math.max(start+1,Math.ceil(visibleRange.end*sourceFrames.length)),frames=sourceFrames.slice(start,end);
  const span=visibleRange.end-visibleRange.start;
  const rangeAt=(left:number,size=span)=>({start:Math.min(1-size,Math.max(0,left)),end:Math.min(1-size,Math.max(0,left))+size});
  const local = useRef<StoreApi<{width:number}> | null>(null);
  if (!local.current) local.current = createStore(() => ({width:0}));
  const store = local.current;
  const width = useStore(store, s => s.width);
  const statusText = status === "measuring" ? "Analysing spectrum" : status === "error" ? (error ?? "Spectrum could not be analysed")
    : status === "empty" ? "Nothing to analyse" : "Spectrum ready";
  useStatusAnnouncement(statusText);
  const muted = !unstyled ? "text-text-muted" : undefined;
  const plotWidth = Math.max(0, width - AXIS);
  const ready = status === "ready" && frames.length > 0 && bandsHz.length > 0;
  const grid = ready && plotWidth > 0
    ? poolSpectrogram(frames, bandsHz.length, columnsForWidth(plotWidth, frames.length)) : undefined;
  const runs = grid ? spectrogramRuns(grid) : [];
  const duration = frames.length * hopSeconds;
  // Whole-point edges so neighbouring runs share a boundary with no seam.
  const edges = (column: number, span: number, row: number) => {
    const x0 = Math.round(column * plotWidth / grid!.columns), x1 = Math.round((column + span) * plotWidth / grid!.columns);
    const y0 = Math.round(row * height / grid!.rows), y1 = Math.round((row + 1) * height / grid!.rows);
    return { position: "absolute" as const, left: x0, width: x1 - x0, bottom: y0, height: y1 - y0 };
  };
  const summary = ready ? describeSpectrogram(frames, bandsHz, hopSeconds) : statusText;

  let body;
  if (status === "measuring") {
    body = <View style={{ gap: space[2] }}>
      <Text accessibilityLiveRegion="polite" {...{ className: muted }} style={{ fontSize: font[13] }}>Analysing the spectrum of the selected range</Text>
      <View aria-hidden {...{ className: joinClasses(!unstyled && "rounded-control bg-surface-sunken") }} style={{ height }} />
    </View>;
  } else if (status === "error") {
    body = <View accessibilityRole="alert"><Text selectable {...{ className: joinClasses(!unstyled && "text-text") }} style={{ fontSize: font[14] }}>
      {error ?? "The spectrum could not be analysed."}</Text></View>;
  } else if (!ready) {
    body = <Text accessibilityLiveRegion="polite" {...{ className: muted }} style={{ fontSize: font[14] }}>
      There is no audio in this range to analyse. Select a range with audio.
    </Text>;
  } else {
    body = <View style={{ gap: space[1.5], direction: "ltr" }}>
      <View role="img" accessibilityLabel={summary} onLayout={e => store.setState({width:e.nativeEvent.layout.width})}
        style={{ flexDirection: "row", height }}>
        <View aria-hidden style={{ width: AXIS, height }}>
          {frequencyTicks(bandsHz).map(t => <Text key={t.label} {...{ className: muted }}
            style={{ position: "absolute", right: 8, fontSize: font[11], fontVariant: ["tabular-nums"],
              top: Math.min(height - 14, Math.max(0, height * (1 - t.position) - 7)) }}>{t.label}</Text>)}
        </View>
        <View aria-hidden testID={props.testID ? props.testID + "-plot" : undefined}
          {...{ className: joinClasses(!unstyled && "rounded-control bg-surface-sunken") }}
          style={{ flex: 1, height, overflow: "hidden" }}>
          {grid ? runs.map(r => <View key={r.row + ":" + r.column} {...{ className: joinClasses(!unstyled && STEP_CLASS[r.step]) }}
            style={edges(r.column, r.span, r.row)} />) : null}
        </View>
      </View>
      <View aria-hidden style={{ marginLeft: AXIS, height: 16 }}>
        {timeTicks(duration).map((t, i, all) => <Text key={t.label} {...{ className: muted }}
          style={{ position: "absolute", fontSize: font[11], fontVariant: ["tabular-nums"],
            ...(i === 0 ? { left: 0 } : i === all.length - 1 && t.position > 0.92
              ? { right: ((1 - t.position) * 100) + "%" }
              : { left: (t.position * 100) + "%", transform: [{ translateX: "-50%" }] }) }}>{t.label}</Text>)}
      </View>
      <View aria-hidden style={{ flexDirection: "row", alignItems: "center", gap: space[1.5], marginLeft: AXIS, flexWrap: "wrap" }}>
        <Text {...{ className: muted }} style={{ fontSize: font[11] }}>Quiet</Text>
        {([1, 2, 3, 4, 5] as const).map(s => <View key={s} {...{ className: joinClasses(!unstyled && STEP_CLASS[s], !unstyled && "rounded-sm") }}
          style={{ width: 16, height: 10 }} />)}
        <Text {...{ className: muted }} style={{ fontSize: font[11] }}>
          {"Loud (steps at " + SPECTROGRAM_THRESHOLDS_DB.map(d => "−" + -d).join(", ") + " dB)"}
        </Text>
      </View>
    </View>;
  }

  return <View {...props} role="group" aria-label={label} aria-busy={status === "measuring" || undefined}
    {...{ className: joinClasses(!unstyled && "rounded-card border border-border bg-surface-raised", className) }}
    style={[{ padding: space[4], gap: space[3] }, style]}>
    <Text role="heading" aria-level={3} {...{ className: joinClasses(!unstyled && "text-text font-semibold") }} style={{ fontSize: font[15] }}>{label}</Text>
    {onVisibleRangeCommit?<View style={{flexDirection:'row',flexWrap:'wrap',gap:space[1.5]}}>
     <Button title="Zoom into spectrum" disabled={disabledReason!==undefined||sourceFrames.length<2||span<=1/Math.max(1,sourceFrames.length)} unstyled={unstyled} onPress={()=>onVisibleRangeCommit(rangeAt(visibleRange.start+span/4,Math.max(1/Math.max(1,sourceFrames.length),span/2)))}/>
     <Button title="Zoom out of spectrum" disabled={disabledReason!==undefined||span>=1} unstyled={unstyled} onPress={()=>onVisibleRangeCommit(rangeAt(visibleRange.start-span/2,Math.min(1,span*2)))}/>
     <Button title="Earlier spectrum" disabled={disabledReason!==undefined||visibleRange.start===0} unstyled={unstyled} onPress={()=>onVisibleRangeCommit(rangeAt(visibleRange.start-span/2))}/>
     <Button title="Later spectrum" disabled={disabledReason!==undefined||visibleRange.end===1} unstyled={unstyled} onPress={()=>onVisibleRangeCommit(rangeAt(visibleRange.start+span/2))}/>
    </View>:null}
    <Text {...{className:muted}}>Source window {(start*hopSeconds).toFixed(3)}–{(Math.min(end,sourceFrames.length)*hopSeconds).toFixed(3)} s</Text>
    {body}<ErrorMessage message={actionError??disabledReason} unstyled={unstyled}/>
  </View>;
}

import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

